,"sentiment_archived":true,"sentiment_week_key":"2026-01-05"},{"id":"past-fb-B2249","guest_name":"Luis Navarro","guest_email":"past-b2249@imported.elenest.local","booking_id":"past-B2249","stars":5,"comment":"We had a wonderful and relaxing stay., The water in the pool was a bit cloudy.","photo_url":"","created_at":"2026-01-09T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-01-05"},{"id":"past-fb-B2250","guest_name":"Joshua Mercado","guest_email":"past-b2250@imported.elenest.local","booking_id":"past-B2250","stars":2,"comment":"May ilang sira sa banyo.. In addition, A bit overpriced for the current state.","photo_url":"","created_at":"2026-01-09T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-01-05"}]$elenest_hist$::jsonb) as x(
  id text,
  guest_name text,
  guest_email text,
  booking_id text,
  stars int,
  comment text,
  photo_url text,
  created_at text,
  sentiment_archived boolean,
  sentiment_week_key text
)
on conflict (id) do update set
  guest_name = excluded.guest_name,
  guest_email = excluded.guest_email,
  booking_id = excluded.booking_id,
  stars = excluded.stars,
  comment = excluded.comment,
  created_at = excluded.created_at,
  sentiment_archived = excluded.sentiment_archived,
  sentiment_week_key = excluded.sentiment_week_key
where public.guest_feedback.id like 'past-fb-%';

-- feedback 4/6
insert into public.guest_feedback (
  id, guest_name, guest_email, booking_id, stars, comment, photo_url,
  created_at, sentiment_archived, sentiment_week_key
)
select
  x.id, x.guest_name, x.guest_email, x.booking_id, x.stars, x.comment, x.photo_url,
  x.created_at::timestamptz, x.sentiment_archived, x.sentiment_week_key
