,{"id":"past-fb-B2498","guest_name":"Ana Torres","guest_email":"past-b2498@imported.elenest.local","booking_id":"past-B2498","stars":4,"comment":"The room cleanliness was disappointing.. Also, Madaling hanapin ang lokasyon.","photo_url":"","created_at":"2026-01-30T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-01-26"},{"id":"past-fb-B2499","guest_name":"Ana Del Rosario","guest_email":"past-b2499@imported.elenest.local","booking_id":"past-B2499","stars":4,"comment":"Mabagal ang serbisyo sa reception.. Legit na relaxing ang vibe.","photo_url":"","created_at":"2026-01-30T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-01-26"},{"id":"past-fb-B2500","guest_name":"Melvin Torres","guest_email":"past-b2500@imported.elenest.local","booking_id":"past-B2500","stars":4,"comment":"Facilities are a bit outdated.. Legit na relaxing ang vibe.","photo_url":"","created_at":"2026-01-30T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-01-26"}]$elenest_hist$::jsonb) as x(
  id text,
  guest_name text,
  guest_email text,
  booking_id text,
  stars int,
  comment text,
  photo_url text,
  created_at text,
  sentiment_archived boolean,
  sentiment_week_key text
)
on conflict (id) do update set
  guest_name = excluded.guest_name,
  guest_email = excluded.guest_email,
  booking_id = excluded.booking_id,
  stars = excluded.stars,
  comment = excluded.comment,
  created_at = excluded.created_at,
  sentiment_archived = excluded.sentiment_archived,
  sentiment_week_key = excluded.sentiment_week_key
where public.guest_feedback.id like 'past-fb-%';

-- feedback 5/6
insert into public.guest_feedback (
  id, guest_name, guest_email, booking_id, stars, comment, photo_url,
  created_at, sentiment_archived, sentiment_week_key
)
select
