  id text,
  guest_name text,
  guest_email text,
  booking_id text,
  stars int,
  comment text,
  photo_url text,
  created_at text,
  sentiment_archived boolean,
  sentiment_week_key text
)
on conflict (id) do update set
  guest_name = excluded.guest_name,
  guest_email = excluded.guest_email,
  booking_id = excluded.booking_id,
  stars = excluded.stars,
  comment = excluded.comment,
  created_at = excluded.created_at,
  sentiment_archived = excluded.sentiment_archived,
  sentiment_week_key = excluded.sentiment_week_key
where public.guest_feedback.id like 'past-fb-%';

-- feedback 6/6
insert into public.guest_feedback (
  id, guest_name, guest_email, booking_id, stars, comment, photo_url,
  created_at, sentiment_archived, sentiment_week_key
)
select
  x.id, x.guest_name, x.guest_email, x.booking_id, x.stars, x.comment, x.photo_url,
  x.created_at::timestamptz, x.sentiment_archived, x.sentiment_week_key
