alo ang view, seryoso., The environment was too loud for relaxation.","photo_url":"","created_at":"2026-03-09T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-03-09"},{"id":"past-fb-B2999","guest_name":"Carmen Domingo","guest_email":"past-b2999@imported.elenest.local","booking_id":"past-B2999","stars":2,"comment":"Napakaganda ng inyong resort., We encountered some issues with the water pressure.","photo_url":"","created_at":"2026-03-09T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-03-09"},{"id":"past-fb-B3000","guest_name":"Ana Reyes","guest_email":"past-b3000@imported.elenest.local","booking_id":"past-B3000","stars":5,"comment":"Solid ang experience rito.. In addition, Maayos ang pamamalakad sa lugar.","photo_url":"","created_at":"2026-03-09T12:00:00+08:00","sentiment_archived":true,"sentiment_week_key":"2026-03-09"}]$elenest_hist$::jsonb) as x(
  id text,
  guest_name text,
  guest_email text,
  booking_id text,
  stars int,
  comment text,
  photo_url text,
  created_at text,
  sentiment_archived boolean,
  sentiment_week_key text
)
on conflict (id) do update set
  guest_name = excluded.guest_name,
  guest_email = excluded.guest_email,
  booking_id = excluded.booking_id,
  stars = excluded.stars,
  comment = excluded.comment,
  created_at = excluded.created_at,
  sentiment_archived = excluded.sentiment_archived,
  sentiment_week_key = excluded.sentiment_week_key
where public.guest_feedback.id like 'past-fb-%';

commit;

